def get_icon_svg(name: str, size: int = 18, color: str = "#2563EB", stroke: float = 2.0) -> str:
    """Returns an inline SVG string for the specified icon name."""
    template = SVG_TEMPLATES.get(name, SVG_TEMPLATES["dashboard"])
    return template.format(size=size, color=color, stroke=stroke)

# Aliases for flexible import
get_icon = get_icon_svg

def render_icon_badge(name: str, size: int = 20, color: str = "#2563EB", bg_color: str = "#EFF6FF") -> str:
    """Returns an inline HTML pill wrapping the SVG icon."""
    svg = get_icon(name, size=size, color=color)
    return f"""
    <div style="display:inline-flex; align-items:center; justify-content:center; width:{size+14}px; height:{size+14}px; border-radius:10px; background:{bg_color}; border:1px solid #DBEAFE;">
        {svg}
    </div>
    """
